import React, { useState } from "react";

const FeedbackModal = ({ onClose }) => {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    feedback: "",
  });
  const [result, setResult] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const onSubmit = async (event) => {
    event.preventDefault();
    setIsSubmitting(true);

    const formDataObj = new FormData(event.target);
    formDataObj.append("access_key", "8efe6827-4c43-4142-bef5-43beb1467900");

    try {
      const response = await fetch("https://api.web3forms.com/submit", {
        method: "POST",
        body: formDataObj,
      });

      const data = await response.json();

      if (data.success) {
        setResult("Success! Thank you for your feedback.");
        setTimeout(() => {
          setResult("");
          setFormData({ name: "", email: "", feedback: "" });
          onClose();
        }, 2000);
      } else {
        setResult("Error! Please try again.");
      }
    } catch (error) {
      console.error("Error submitting form:", error);
      setResult("Error! Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div
      style={{
        padding: "20px 40px 40px 40px",
        textAlign: "center",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        minHeight: "100%",
        maxWidth: "600px",
        margin: "0 auto",
        overflow: "auto",
        paddingTop: "60px",
      }}
    >
      <h3
        style={{
          color: "white",
          fontSize: "2rem",
          marginBottom: "20px",
          fontWeight: "400",
        }}
      >
        Share Your Feedback
      </h3>
      <p
        style={{
          color: "#9ca3af",
          fontSize: "1.2rem",
          marginBottom: "30px",
          lineHeight: "1.5",
        }}
      >
        We value your thoughts and suggestions to help us improve.
      </p>

      <div style={{ width: "100%", maxWidth: "500px" }}>
        {!result.includes("Success") ? (
          <form onSubmit={onSubmit} style={{ width: "100%" }}>
            <input
              type="text"
              name="name"
              value={formData.name}
              onChange={(e) =>
                setFormData({ ...formData, name: e.target.value })
              }
              placeholder="Your Name"
              required
              disabled={isSubmitting}
              style={{
                width: "100%",
                padding: "15px 20px",
                fontSize: "1rem",
                border: "1px solid #3cb6ab",
                backgroundColor: "rgba(0, 0, 0, 0.3)",
                color: "white",
                marginBottom: "20px",
                outline: "none",
                boxSizing: "border-box",
              }}
            />
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={(e) =>
                setFormData({ ...formData, email: e.target.value })
              }
              placeholder="your.email@example.com"
              required
              disabled={isSubmitting}
              style={{
                width: "100%",
                padding: "15px 20px",
                fontSize: "1rem",
                border: "1px solid #3cb6ab",
                backgroundColor: "rgba(0, 0, 0, 0.3)",
                color: "white",
                marginBottom: "20px",
                outline: "none",
                boxSizing: "border-box",
              }}
            />
            <textarea
              name="message"
              value={formData.feedback}
              onChange={(e) =>
                setFormData({ ...formData, feedback: e.target.value })
              }
              placeholder="Please share your feedback, suggestions, or ideas..."
              required
              disabled={isSubmitting}
              rows={5}
              style={{
                width: "100%",
                padding: "15px 20px",
                fontSize: "1rem",
                border: "1px solid #3cb6ab",
                backgroundColor: "rgba(0, 0, 0, 0.3)",
                color: "white",
                marginBottom: "20px",
                outline: "none",
                boxSizing: "border-box",
                resize: "vertical",
                fontFamily: "inherit",
              }}
            />
            <button
              type="submit"
              disabled={isSubmitting}
              style={{
                width: "100%",
                padding: "15px 20px",
                fontSize: "1rem",
                fontWeight: "500",
                border: "1px solid #3cb6ab",
                backgroundColor: "#3cb6ab",
                color: "black",
                cursor: isSubmitting ? "not-allowed" : "pointer",
                boxSizing: "border-box",
                opacity: isSubmitting ? 0.6 : 1,
              }}
            >
              {isSubmitting ? "Sending..." : "Send Feedback"}
            </button>
            {result && (
              <p
                style={{
                  marginTop: "15px",
                  color: result.includes("Success") ? "#3cb6ab" : "#ff6464",
                  fontSize: "1rem",
                  fontWeight: "500",
                }}
              >
                {result}
              </p>
            )}
          </form>
        ) : (
          <div
            style={{
              padding: "20px",
              border: "1px solid #3cb6ab",
              backgroundColor: "rgba(60, 182, 171, 0.1)",
              color: "#3cb6ab",
              fontSize: "1.1rem",
            }}
          >
            ✓ {result}
          </div>
        )}
      </div>
    </div>
  );
};

export default FeedbackModal;
