import React, { useState } from "react";

const ContactForm = ({ onClose }) => {
  const [email, setEmail] = useState("");
  const [result, setResult] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const onSubmit = async (event) => {
    event.preventDefault();
    setIsSubmitting(true);

    const formData = new FormData(event.target);
    formData.append("access_key", "8efe6827-4c43-4142-bef5-43beb1467900");

    try {
      const response = await fetch("https://api.web3forms.com/submit", {
        method: "POST",
        body: formData,
      });

      const data = await response.json();

      if (data.success) {
        setResult("Success! We'll be in touch soon.");
        setTimeout(() => {
          setResult("");
          setEmail("");
          onClose();
        }, 2000);
      } else {
        setResult("Error! Please try again.");
      }
    } catch (error) {
      console.error("Error submitting form:", error);
      setResult("Error! Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div
      style={{
        padding: "40px",
        textAlign: "center",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100%",
        maxWidth: "600px",
        margin: "0 auto",
      }}
    >
      <h3
        style={{
          color: "white",
          fontSize: "2rem",
          marginBottom: "20px",
          fontWeight: "400",
        }}
      >
        Get in Touch
      </h3>
      <p
        style={{
          color: "#9ca3af",
          fontSize: "1.2rem",
          marginBottom: "30px",
          lineHeight: "1.5",
        }}
      >
        We'd love to hear from you! Reach out to us at:
      </p>
      <div
        style={{
          padding: "20px 30px",
          marginBottom: "40px",
        }}
      >
        <a
          href="mailto:contact@accelbia.design?subject=I am interested in working with you"
          style={{
            color: "#3cb6ab",
            fontSize: "1.5rem",
            textDecoration: "none",
            fontWeight: "500",
            transition: "color 0.2s ease, filter 0.2s ease",
          }}
          onMouseEnter={(e) => {
            e.target.style.color = "white";
            e.target.style.filter =
              "drop-shadow(0 0 5px #3cb6ab) drop-shadow(0 0 10px #3cb6ab) drop-shadow(0 0 15px #3cb6ab)";
          }}
          onMouseLeave={(e) => {
            e.target.style.color = "#3cb6ab";
            e.target.style.filter = "none";
          }}
        >
          contact@accelbia.design
        </a>
      </div>

      <div style={{ width: "100%", maxWidth: "400px" }}>
        <p
          style={{
            color: "#9ca3af",
            fontSize: "1rem",
            marginBottom: "20px",
            lineHeight: "1.5",
          }}
        >
          Or leave your email and we'll contact you:
        </p>

        {!result.includes("Success") ? (
          <form onSubmit={onSubmit} style={{ width: "100%" }}>
            <input
              type="email"
              name="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="your.email@example.com"
              required
              disabled={isSubmitting}
              style={{
                width: "100%",
                padding: "15px 20px",
                fontSize: "1rem",
                border: "1px solid #3cb6ab",
                backgroundColor: "rgba(0, 0, 0, 0.3)",
                color: "white",
                marginBottom: "20px",
                outline: "none",
                boxSizing: "border-box",
                opacity: isSubmitting ? 0.6 : 1,
              }}
            />
            <button
              type="submit"
              disabled={isSubmitting}
              style={{
                width: "100%",
                padding: "15px 20px",
                fontSize: "1rem",
                fontWeight: "500",
                border: "1px solid #3cb6ab",
                backgroundColor: "#3cb6ab",
                color: "black",
                cursor: isSubmitting ? "not-allowed" : "pointer",
                boxSizing: "border-box",
                opacity: isSubmitting ? 0.6 : 1,
              }}
            >
              {isSubmitting ? "Sending..." : "Send Email"}
            </button>
            {result && (
              <p
                style={{
                  marginTop: "15px",
                  color: result.includes("Success") ? "#3cb6ab" : "#ff6464",
                  fontSize: "1rem",
                  fontWeight: "500",
                }}
              >
                {result}
              </p>
            )}
          </form>
        ) : (
          <div
            style={{
              padding: "20px",
              border: "1px solid #3cb6ab",
              backgroundColor: "rgba(60, 182, 171, 0.1)",
              color: "#3cb6ab",
              fontSize: "1.1rem",
            }}
          >
            ✓ {result}
          </div>
        )}
      </div>
    </div>
  );
};

export default ContactForm;
