import React, { useState } from "react";
import "./footer.css";
import { SocialIcon } from "react-social-icons";
import FullscreenModal from "../fs-modal";
import ContactForm from "../navbar/ContactForm";
import AboutModal from "../navbar/AboutModal";
import FeedbackModal from "../navbar/FeedbackModal";

const Footer = () => {
  const [email, setEmail] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [message, setMessage] = useState("");
  const [isSubscribed, setIsSubscribed] = useState(false);
  const [isContactModalVisible, setIsContactModalVisible] = useState(false);
  const [isAboutModalVisible, setIsAboutModalVisible] = useState(false);
  const [hoveredIcon, setHoveredIcon] = useState(null);
  const [isFeedbackModalVisible, setIsFeedbackModalVisible] = useState(false);

  const validateEmail = (email) => {
    const re = /\S+@\S+\.\S+/;
    return re.test(email);
  };

  async function subscribe(event) {
    event.preventDefault();

    if (!validateEmail(email)) {
      setMessage("Please enter a valid email address.");
      return;
    }

    setIsSubmitting(true);
    setMessage("");

    try {
      const formData = new FormData();
      formData.append("access_key", "8efe6827-4c43-4142-bef5-43beb1467900");
      formData.append("subject", "Newsletter Subscription Request");
      formData.append("email", email);
      formData.append(
        "message",
        `Newsletter subscription request from: ${email}`
      );
      formData.append("from_name", "Website Newsletter Form");

      const response = await fetch("https://api.web3forms.com/submit", {
        method: "POST",
        body: formData,
      });

      const data = await response.json();

      if (data.success) {
        setIsSubscribed(true);
        setEmail("");
        // Reset button after 3 seconds
        setTimeout(() => {
          setIsSubscribed(false);
        }, 3000);
      } else {
        console.error("Error:", data);
        setMessage("Subscription failed. Please try again.");
      }
    } catch (error) {
      console.error(error);
      setMessage("An error occurred. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  }

  const handleNavigation = (e, type) => {
    e.preventDefault();

    switch (type) {
      case "about":
        setIsAboutModalVisible(true);
        break;
      case "contact":
        setIsContactModalVisible(true);
        break;
      case "feedback":
        setIsFeedbackModalVisible(true);
        break;
      case "explore":
        window.location.href = "/explore";
        break;
      case "work_with_us":
        window.location.href = "/work_with_us";
        break;
      default:
        break;
    }
  };

  return (
    <>
      {/* About Modal */}
      <FullscreenModal
        isVisible={isAboutModalVisible}
        title="About Us"
        component={<AboutModal onClose={() => setIsAboutModalVisible(false)} />}
        onClose={() => setIsAboutModalVisible(false)}
      />

      {/* Contact Modal */}
      <FullscreenModal
        isVisible={isContactModalVisible}
        title="Contact Us"
        component={
          <ContactForm onClose={() => setIsContactModalVisible(false)} />
        }
        onClose={() => setIsContactModalVisible(false)}
      />

      {/* Feedback Modal */}
      <FullscreenModal
        isVisible={isFeedbackModalVisible}
        title="Feedback"
        component={
          <FeedbackModal onClose={() => setIsFeedbackModalVisible(false)} />
        }
        onClose={() => setIsFeedbackModalVisible(false)}
      />

      <footer className="footer">
        <div className="col">
          <p
            style={{
              color: "rgba(255, 255, 255, 0.5)",
              fontWeight: "300",
            }}
          >
            © {new Date().getFullYear()} accelbia.design
          </p>

          <form className="subscribe" onSubmit={subscribe}>
            <h4
              style={{
                color: "rgba(255, 255, 255, 0.5)",
                fontWeight: "300",
              }}
            >
              Wanna stay posted?
            </h4>

            <div className="form-inputs">
              <input
                type="email"
                name="email"
                id="email"
                placeholder="Email Address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                disabled={isSubmitting || isSubscribed}
                aria-label="Email address for newsletter subscription"
              />
              <button
                type="submit"
                disabled={isSubmitting || isSubscribed}
                aria-label="Subscribe to newsletter"
                style={{
                  color: isSubscribed ? "#3cb6ab" : "",
                  borderColor: isSubscribed ? "#3cb6ab" : "",
                }}
              >
                {isSubmitting
                  ? "Subscribing..."
                  : isSubscribed
                  ? "Subscribed"
                  : "Subscribe"}
              </button>
            </div>
            {message && (
              <p
                className={`message ${
                  message.includes("successfully") ? "success" : "error"
                }`}
              >
                {message}
              </p>
            )}
          </form>

          <div className="social">
            <SocialIcon
              url="https://x.com/accelbia_design"
              target="_blank"
              bgColor={hoveredIcon === "twitter" ? "#3cb6ab" : "#fff"}
              fgColor={hoveredIcon === "twitter" ? "#fff" : "#000"}
              style={{
                height: 30,
                width: 30,
                transition: "all 0.3s ease",
              }}
              onMouseEnter={() => setHoveredIcon("twitter")}
              onMouseLeave={() => setHoveredIcon(null)}
            />
            <SocialIcon
              url="https://www.facebook.com/accelbia.design/"
              target="_blank"
              bgColor={hoveredIcon === "facebook" ? "#3cb6ab" : "#fff"}
              fgColor={hoveredIcon === "facebook" ? "#fff" : "#000"}
              style={{
                height: 30,
                width: 30,
                transition: "all 0.3s ease",
              }}
              onMouseEnter={() => setHoveredIcon("facebook")}
              onMouseLeave={() => setHoveredIcon(null)}
            />
            <SocialIcon
              url="https://instagram.com/accelbia.design"
              target="_blank"
              bgColor={hoveredIcon === "instagram" ? "#3cb6ab" : "#fff"}
              fgColor={hoveredIcon === "instagram" ? "#fff" : "#000"}
              style={{
                height: 30,
                width: 30,
                transition: "all 0.3s ease",
              }}
              onMouseEnter={() => setHoveredIcon("instagram")}
              onMouseLeave={() => setHoveredIcon(null)}
            />
            <SocialIcon
              url="https://www.linkedin.com/company/accelbia-design/"
              target="_blank"
              bgColor={hoveredIcon === "linkedin" ? "#3cb6ab" : "#fff"}
              fgColor={hoveredIcon === "linkedin" ? "#fff" : "#000"}
              style={{
                height: 30,
                width: 30,
                transition: "all 0.3s ease",
              }}
              onMouseEnter={() => setHoveredIcon("linkedin")}
              onMouseLeave={() => setHoveredIcon(null)}
            />
            <SocialIcon
              url="https://www.youtube.com/@accelbia.design"
              bgColor={hoveredIcon === "youtube" ? "#3cb6ab" : "#fff"}
              fgColor={hoveredIcon === "youtube" ? "#fff" : "#000"}
              style={{
                height: 30,
                width: 30,
                transition: "all 0.3s ease",
              }}
              onMouseEnter={() => setHoveredIcon("youtube")}
              onMouseLeave={() => setHoveredIcon(null)}
            />
          </div>
        </div>

        <div className="col">
          <h4>Quick Links</h4>
          <ul>
            <li>
              <a
                href="#"
                onClick={(e) => handleNavigation(e, "about")}
                key={"about"}
              >
                About
              </a>
            </li>
            <li>
              <a
                href="#"
                onClick={(e) => handleNavigation(e, "contact")}
                key={"contact"}
              >
                Contact
              </a>
            </li>
            <li>
              <a
                href="#"
                onClick={(e) => handleNavigation(e, "feedback")}
                key={"feedback"}
              >
                Feedback
              </a>
            </li>
            <li>
              <a href="https://blog.accelbia.design/" key={"blog"}>
                Blog
              </a>
            </li>
            <li>
              <a
                href="#"
                onClick={(e) => handleNavigation(e, "work_with_us")}
                key={"work_with_us"}
              >
                Work With Us
              </a>
            </li>
          </ul>
        </div>
      </footer>
    </>
  );
};

export default Footer;
