import "./Navbar.css";
import { useState, useEffect } from "react";
import NavLogo from "./navlogo/NavLogo";
import MenuIcon from "@mui/icons-material/Menu";
import CloseIcon from "@mui/icons-material/Close";
import FullscreenModal from "../fs-modal";
import ContactForm from "./ContactForm";
import AboutModal from "./AboutModal";

const Navbar = () => {
  const [screenWidth, setScreenWidth] = useState(window.innerWidth);
  const [screenHeight, setScreenHeight] = useState(window.innerHeight);
  const [scrollY, setScrollY] = useState(0);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isContactModalVisible, setIsContactModalVisible] = useState(false);
  const [isAboutModalVisible, setIsAboutModalVisible] = useState(false);

  useEffect(() => {
    const handleResize = () => {
      setScreenWidth(window.innerWidth);
      setScreenHeight(window.innerHeight);
      if (window.innerWidth > 768) {
        setIsMobileMenuOpen(false);
      }
    };

    const handleScroll = () => {
      setScrollY(window.scrollY);
    };

    window.addEventListener("resize", handleResize);
    window.addEventListener("scroll", handleScroll);

    return () => {
      window.removeEventListener("resize", handleResize);
      window.removeEventListener("scroll", handleScroll);
    };
  }, [screenWidth, screenHeight, scrollY]);

  useEffect(() => {
    if (isMobileMenuOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }

    return () => {
      document.body.style.overflow = "unset";
    };
  }, [isMobileMenuOpen]);

  const button_redirect = (e) => {
    const button = e.target.id;
    setIsMobileMenuOpen(false);

    switch (button) {
      case "about":
        setIsAboutModalVisible(true);
        break;
      case "contact":
        setIsContactModalVisible(true);
        break;
      case "explore":
        window.location.href = "/explore";
        break;
      case "work_with_us":
        window.location.href = "/work_with_us";
        break;
      case "blog":
        window.location.href = "https://blog.accelbia.design";
        break;
      default:
        break;
    }
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  const isMobile = screenWidth <= 768;

  return (
    <>
      {/* About Modal */}
      <FullscreenModal
        isVisible={isAboutModalVisible}
        title="About Us"
        component={<AboutModal onClose={() => setIsAboutModalVisible(false)} />}
        onClose={() => setIsAboutModalVisible(false)}
      />

      {/* Contact Modal */}
      <FullscreenModal
        isVisible={isContactModalVisible}
        title="Contact Us"
        component={
          <ContactForm onClose={() => setIsContactModalVisible(false)} />
        }
        onClose={() => setIsContactModalVisible(false)}
      />

      <nav
        className="navbar"
        role="navigation"
        aria-label="Main navigation"
        style={{
          transition: "all 0.5s ease",
          backgroundColor: scrollY > 10 ? "rgba(0, 0, 0, 0.3)" : "transparent",
          backdropFilter: scrollY > 10 ? "blur(10px)" : "none",
          borderBottom:
            scrollY > 10 ? "none" : "1px solid rgba(255, 255, 255, 0.2)",
        }}
      >
        <NavLogo />

        {!isMobile && (
          <div
            className="navbar-right"
            style={{
              flexDirection: scrollY < 10 ? "column" : "row",
            }}
          >
            <button
              type="button"
              id="about"
              onClick={button_redirect}
              aria-label="Go to About page"
            >
              About
            </button>
            <button
              type="button"
              id="contact"
              onClick={button_redirect}
              aria-label="Go to Contact page"
            >
              Contact
            </button>
            <button
              type="button"
              id="explore"
              onClick={button_redirect}
              aria-label="Go to Explore page"
            >
              Explore
            </button>
            <button
              type="button"
              id="work_with_us"
              onClick={button_redirect}
              aria-label="Go to Work With Us page"
            >
              Work With Us
            </button>
            <button
              type="button"
              id="blog"
              onClick={button_redirect}
              aria-label="Visit our blog"
            >
              Blog
            </button>
          </div>
        )}

        {isMobile &&
          (isMobileMenuOpen ? (
            <CloseIcon
              className="mobile-menu-icon"
              onClick={toggleMobileMenu}
              aria-label="Close mobile menu"
              role="button"
              tabIndex={0}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  toggleMobileMenu();
                }
              }}
            />
          ) : (
            <MenuIcon
              className="mobile-menu-icon"
              onClick={toggleMobileMenu}
              aria-label="Open mobile menu"
              role="button"
              tabIndex={0}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  toggleMobileMenu();
                }
              }}
            />
          ))}
      </nav>

      {isMobile && (
        <>
          <div
            className={`mobile-overlay ${isMobileMenuOpen ? "active" : ""}`}
            onClick={() => setIsMobileMenuOpen(false)}
            aria-hidden="true"
          />

          <div className={`mobile-drawer ${isMobileMenuOpen ? "active" : ""}`}>
            <div className="drawer-header">
              <CloseIcon
                className="drawer-close-icon"
                onClick={toggleMobileMenu}
                aria-label="Close mobile menu"
                role="button"
                tabIndex={0}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    toggleMobileMenu();
                  }
                }}
              />
            </div>
            <div className="mobile-menu">
              <button
                type="button"
                id="about"
                onClick={button_redirect}
                className="mobile-menu-item"
              >
                About
              </button>
              <button
                type="button"
                id="contact"
                onClick={button_redirect}
                className="mobile-menu-item"
              >
                Contact
              </button>
              <button
                type="button"
                id="explore"
                onClick={button_redirect}
                className="mobile-menu-item"
              >
                Explore
              </button>
              <button
                type="button"
                id="work_with_us"
                onClick={button_redirect}
                className="mobile-menu-item"
              >
                Work With Us
              </button>
              <button
                type="button"
                id="blog"
                onClick={button_redirect}
                className="mobile-menu-item"
              >
                Blog
              </button>
            </div>
          </div>
        </>
      )}
    </>
  );
};

export default Navbar;
