import React, { useEffect, useRef } from "react";
import { gsap } from "gsap";

const AnimatedIntro = () => {
  const textRef = useRef(null);
  const text =
    "A digital studio based in India leading an intelligent design and automation revolution";

  useEffect(() => {
    const element = textRef.current;
    if (!element) return;

    // Clear any existing content and animations
    gsap.killTweensOf(element);
    element.innerHTML = "";

    // Split text into words and apply special styling to "design" and "automation"
    const words = text.split(" ").map((word, index) => {
      const cleanWord = word.toLowerCase();
      let className = "word";

      if (cleanWord === "design") {
        className = "word design-word";
      } else if (cleanWord === "automation") {
        className = "word automation-word";
      }

      return `<span class="${className}" style="display: inline-block;">${word}</span>`;
    });

    element.innerHTML = words.join(" ");

    // Get all word spans and verify they exist
    const wordElements = element.querySelectorAll(".word");

    if (wordElements.length === 0) {
      console.warn("No word elements found for animation");
      return;
    }

    // Set initial state with error handling
    try {
      gsap.set(wordElements, {
        opacity: 0,
        y: 10,
      });

      // Create typing animation with proper timeline initialization
      const tl = gsap.timeline({
        delay: 1.5,
        onComplete: () => {
          // Animation complete callback
        },
      });

      wordElements.forEach((word, index) => {
        tl.to(
          word,
          {
            opacity: 1,
            y: 0,
            duration: 0.8,
            ease: "power1.out",
          },
          index * 0.25
        );
      });

      // Cleanup function
      return () => {
        if (tl) {
          tl.kill();
        }
        gsap.killTweensOf(wordElements);
      };
    } catch (error) {
      console.error("GSAP animation error:", error);
      // Fallback: show text immediately if animation fails
      gsap.set(wordElements, { opacity: 1, y: 0 });
    }
  }, []);

  return (
    <div
      className="animated-intro-container"
      style={{
        position: "absolute",
        top: "50%",
        left: "50%",
        transform: "translate(-50%, -50%)",
        textAlign: "center",
        width: "95%",
        maxWidth: "1000px",
        padding: "0 20px",
        zIndex: 5,
        boxSizing: "border-box",
      }}
    >
      <h1
        ref={textRef}
        className="very-vogue-display-italic"
        style={{
          fontSize: "clamp(1.2rem, 3.5vw, 2.5rem)",
          fontWeight: "normal",
          fontStyle: "normal",
          color: "white",
          lineHeight: 1.3,
          margin: 0,
          letterSpacing: "0.01em",
          wordWrap: "break-word",
        }}
      />
    </div>
  );
};

export default AnimatedIntro;
